using System;using System.IO;using System.Linq;using System.Runtime.InteropServices;using System.Web.Script.Serialization;using interop.ICApiIronCAD;
namespace RockPro {public static class LatchInProcess {public static int Run(string folder){var j=new JavaScriptSerializer();bool pass=false;string error=null;try{var r=(System.Collections.Generic.Dictionary<string,object>)j.DeserializeObject(File.ReadAllText(Path.Combine(folder,"request.json")));dynamic legacy=Marshal.GetActiveObject("IronCAD.Application");var app=(IZBaseApp)legacy.ZIronCADApp;string path=Path.GetFullPath((string)r["owned_path"]);if(!path.EndsWith("export-graphics-02\\reference-copy.ics",StringComparison.OrdinalIgnoreCase))throw new Exception("Unexpected cleanup target");using(var s=new FileStream(path,FileMode.Open,FileAccess.Read,FileShare.ReadWrite|FileShare.Delete))using(var h=System.Security.Cryptography.SHA256.Create())if(BitConverter.ToString(h.ComputeHash(s)).Replace("-","").ToLowerInvariant()!=(string)r["sha256"])throw new Exception("Disk copy changed");int closed=0;foreach(var x in (Array)app.GetAllOpenDocs()){var d=x as IZDoc;if(d==null)d=(IZDoc)Marshal.GetObjectForIUnknown(new IntPtr(Convert.ToInt64(x)));if(String.Equals(Path.GetFullPath(d.Name),path,StringComparison.OrdinalIgnoreCase)){d.Close2(true);closed++;}}if(closed!=1)throw new Exception("Expected one explicitly owned display copy");pass=true;}catch(Exception e){error=e.ToString();}File.WriteAllText(Path.Combine(folder,"result.json"),j.Serialize(new{passed=pass,error=error,saved=false}));return pass?0:1;}}}
